      console.log(`\u670D\u52A1\u5DF2\u542F\u52A8:`);
      console.log(`\u6253\u5F00\u94FE\u63A5 ${colorsInstance.green(url)} \u5373\u523B\u4F7F\u7528\u5427~`);
      console.log(``);
      const { spaceId, clientSecret } = arg2;
      if (spaceId && clientSecret) {
        console.log(`${colorsInstance.green("\u2705 \u4E91\u5B58\u50A8\u5DF2\u914D\u7F6E\uFF0C\u53EF\u901A\u8FC7\u81EA\u5B9A\u4E49\u4EE3\u7801\u4E0A\u4F20\u56FE\u7247")}`);
      }
      setTimeout(() => openBrowser(url), 1e3);
